<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ $editing=$templateItem!==null;$required='<span class="required-mark">*</span>'; ?>
<span class="status">ADM · WhatsApp</span><h1><?= $editing?'Editar modelo':'Novo modelo' ?></h1><p class="meta">O cadastro organiza o modelo no painel. A criação e aprovação na Meta serão feitas em uma etapa separada.</p>
<?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<form method="post" action="<?= $escape($basePath) ?>/whatsapp/templates<?= $editing?'/'.(int)$templateItem['id']:'' ?>"><?= $csrfField ?><label>Nome interno <?= $required ?><input name="name" required minlength="2" maxlength="120" value="<?= $escape($templateItem['name']??'') ?>" placeholder="Ex.: Retorno sobre curso"></label><label>Nome na Meta <?= $required ?><input name="meta_name" required maxlength="512" pattern="[a-z0-9_]+" value="<?= $escape($templateItem['meta_name']??'') ?>" placeholder="retorno_sobre_curso"></label><div class="row"><div class="col-sm-4"><label>Categoria <?= $required ?><select name="category" required><option value="">Selecione</option><?php foreach(['utility'=>'Utilidade','marketing'=>'Marketing','authentication'=>'Autenticação']as$value=>$label):?><option value="<?= $value ?>" <?= ($templateItem['category']??'')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label></div><div class="col-sm-4"><label>Idioma <?= $required ?><input name="language" required maxlength="20" value="<?= $escape($templateItem['language']??'pt_BR') ?>"></label></div><div class="col-sm-4"><label>Aprovação <?= $required ?><select name="approval_status" required><?php foreach(['draft'=>'Rascunho','pending'=>'Em análise','approved'=>'Aprovado','rejected'=>'Rejeitado']as$value=>$label):?><option value="<?= $value ?>" <?= ($templateItem['approval_status']??'draft')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></label></div></div><label>Texto do modelo <?= $required ?><textarea name="body" required minlength="2" maxlength="4096" rows="7" placeholder="Olá, {{nome}}! Podemos continuar seu atendimento sobre o curso {{curso}}?"><?= $escape($templateItem['body']??'') ?></textarea></label><p class="meta">Variáveis disponíveis: <code>{{nome}}</code>, <code>{{curso}}</code>, <code>{{unidade}}</code> e <code>{{atendente}}</code>.</p><div class="checks"><label><input type="checkbox" name="is_active" value="1" <?= !$editing||(int)$templateItem['is_active']===1?'checked':'' ?>>Modelo ativo</label></div><button type="submit">Salvar modelo</button></form><p><a href="<?= $escape($basePath) ?>/whatsapp/templates">Cancelar</a></p>
